        </Button>
      ) : (
        <span className="shrink-0 ps-2 tabular-nums">{text}</span>
      )}
      {heading ? (
        <span dir="ltr" className="min-w-0 truncate font-mono" title={heading}>
          {heading}
        </span>
      ) : null}
      {writing ? <ShimmerText className="text-[0.75rem]/[1rem] ms-auto">Writing</ShimmerText> : null}
    </div>
  )
}

/** True while the element scrolls sideways, so it only joins the tab order when it has to. */
function useScrollsX<T extends HTMLElement>(enabled: boolean) {
  const ref = React.useRef<T>(null)
  const [scrolls, setScrolls] = React.useState(false)
  React.useEffect(() => {
    const el = ref.current
    if (!enabled || !el || typeof ResizeObserver === "undefined") {
      setScrolls(false)
      return
    }
    const check = () => setScrolls(el.scrollWidth > el.clientWidth + 1)
    check()
    const ro = new ResizeObserver(check)
    ro.observe(el)
    if (el.firstElementChild) ro.observe(el.firstElementChild)
    return () => ro.disconnect()
  }, [enabled])
  return [ref, scrolls] as const
}

/** Side by side rows: context on both sides, removed lines left, added lines right. */
function splitRows(lines: DiffLine[]): Array<{ left?: DiffLine; right?: DiffLine }> {
  const rows: Array<{ left?: DiffLine; right?: DiffLine }> = []
  let i = 0
  while (i < lines.length) {
    const line = lines[i] as DiffLine
    if (line.kind === "context") {
      rows.push({ left: line, right: line })
      i++
      continue
    }
    const removed: DiffLine[] = []
    const added: DiffLine[] = []
    while (lines[i]?.kind === "remove") removed.push(lines[i++] as DiffLine)
    while (lines[i]?.kind === "add") added.push(lines[i++] as DiffLine)
    for (let r = 0; r < Math.max(removed.length, added.length); r++) {
      rows.push({ left: removed[r], right: added[r] })
    }
  }
  return rows
}

/* -------------------------------------------------------------------------------------------------
 * Tone
 * Red and green by default, from the `--chatcn-diff-*` tokens: a tinted row, a 1 px rule and a
 * stronger word highlight. The +/- glyphs and the screen reader labels carry the meaning on their
 * own, so `mono` (grays and weight only) reads the same for people who cannot tell the hues apart.
 * -----------------------------------------------------------------------------------------------*/

const TONES = {
  mono: {
    add: "bg-(color:--chatcn-alpha-200) text-(color:--chatcn-fg) before:bg-(color:--chatcn-fg)",
    remove: "bg-(color:--chatcn-alpha-100) text-(color:--chatcn-fg-subtle) before:bg-(color:--chatcn-border-strong)",
    addWord: "bg-(color:--chatcn-alpha-500) text-(color:--chatcn-fg)",
    removeWord: "bg-(color:--chatcn-alpha-400) text-(color:--chatcn-fg-muted)",
    addGlyph: "text-(color:--chatcn-fg)",
    removeGlyph: "text-(color:--chatcn-fg-subtle)",
    plus: "text-(color:--chatcn-fg)",
    minus: "text-(color:--chatcn-fg-subtle)",
    addGutter: "bg-(color:--chatcn-alpha-200)",
    removeGutter: "bg-(color:--chatcn-alpha-100)",
  },
  color: {
    add: "bg-(color:--chatcn-diff-add-bg) text-(color:--chatcn-fg) before:bg-(color:--chatcn-diff-add-fg)",
    remove: "bg-(color:--chatcn-diff-del-bg) text-(color:--chatcn-fg) before:bg-(color:--chatcn-diff-del-fg)",
    addWord: "bg-(color:--chatcn-diff-add-word-bg) text-(color:--chatcn-fg)",
    removeWord: "bg-(color:--chatcn-diff-del-word-bg) text-(color:--chatcn-fg)",
    addGlyph: "text-(color:--chatcn-diff-add-fg)",
    removeGlyph: "text-(color:--chatcn-diff-del-fg)",
    plus: "text-(color:--chatcn-diff-add-fg)",
    minus: "text-(color:--chatcn-diff-del-fg)",
    addGutter: "bg-(color:--chatcn-diff-add-gutter)",
    removeGutter: "bg-(color:--chatcn-diff-del-gutter)",
  },
} as const

function rowTone(kind: DiffLine["kind"], tone: DiffTone) {
  if (kind === "context") return "text-(color:--chatcn-fg-muted)"
  return cn(
    "before:absolute before:inset-y-0 before:start-0 before:w-px",
    kind === "add" ? TONES[tone].add : TONES[tone].remove,
  )
}

function Num({
  value,
  strong,
  gutter,
}: {
  value?: number
  strong?: boolean
  /** A changed row's number cell takes a deeper step of the row tint, so changes scan down the edge. */
  gutter?: string
}) {
  return (
    <span
      aria-hidden="true"
      className={cn(
        "text-[0.75rem]/[1rem] w-(--diff-num) shrink-0 pe-2 text-end leading-5 tabular-nums select-none",
        strong ? "text-(color:--chatcn-fg-muted)" : "text-(color:--chatcn-fg-subtle)",
        gutter,
      )}
    >
      {value ?? ""}
    </span>
  )
}

function gutterTone(kind: DiffLine["kind"], tone: DiffTone) {
  if (kind === "context") return undefined
  return kind === "add" ? TONES[tone].addGutter : TONES[tone].removeGutter
}

function Glyph({ kind, tone }: { kind: DiffLine["kind"]; tone: DiffTone }) {
  return (
    <span
      aria-hidden="true"
      className={cn(
        "w-5 shrink-0 text-center select-none",
        kind === "add" && cn("font-medium", TONES[tone].addGlyph),
        kind === "remove" && TONES[tone].removeGlyph,
      )}
    >
      {kind === "add" ? "+" : kind === "remove" ? "-" : ""}
    </span>
  )
}

function srLabel(line: DiffLine) {
  if (line.kind === "add") return `Added line ${line.newNumber}: `
  if (line.kind === "remove") return `Removed line ${line.oldNumber}: `
  return ""
}

function Segments({ segments, word }: { segments: DiffSegment[]; word: string }) {
  return (
    <>
      {segments.map((segment, i) =>
        segment.changed ? (
          <span key={i} className={cn("rounded-[2px] [box-decoration-break:clone]", word)}>
            {segment.text}
          </span>
        ) : (
          <React.Fragment key={i}>{segment.text}</React.Fragment>
        ),
      )}
    </>
  )
}

type StreamingCaretStatus = "streaming" | "waiting" | "done"

interface StreamingCaretProps extends Omit<React.ComponentProps<"span">, "children"> {
  /**
   * `streaming` is solid, `waiting` blinks slowly, `done` removes the caret. Defaults to
   * `streaming`.
   */
  status?: StreamingCaretStatus
  /**
   * Pass the streamed text (or anything that changes with each token). While it keeps changing
   * the caret stays solid; once it holds still for `idleMs` the caret starts to blink.
   */
  activity?: unknown
  /** Quiet time before the caret switches to blinking. Defaults to 600 ms. */
  idleMs?: number
}

/**
 * The signature mark: a small rounded square that means "the model is writing here". It sits on
 * the text baseline at 0.55em, so it scales with whatever text it follows. Solid while tokens flow,
 * a slow 1.2 s blink only while waiting, gone when done. Static under reduced motion.
 */
function StreamingCaret({
  status = "streaming",
  activity,
  idleMs = 600,
  className,
  ...props
}: StreamingCaretProps) {
  const [idle, setIdle] = React.useState(false)
  const tracking = activity !== undefined && status === "streaming"

  React.useEffect(() => {
    if (!tracking) return
    setIdle(false)
    const id = window.setTimeout(() => setIdle(true), idleMs)
    return () => window.clearTimeout(id)
  }, [activity, tracking, idleMs])

  if (status === "done") return null
  const blinking = status === "waiting" || (tracking && idle)

  return (
    <span
      aria-hidden="true"
      data-slot="streaming-caret"
      data-caret-state={blinking ? "waiting" : "streaming"}
      className={cn(
        "bg-(color:--chatcn-accent) ms-0.5 inline-block size-[0.55em] translate-y-[0.04em] rounded-[0.12em] align-baseline forced-colors:bg-[CanvasText]",
        blinking &&
          "animate-[chatcn-caret-blink_1.2s_steps(1,end)_infinite] motion-reduce:animate-none",
        className,
      )}
      {...props}
    />
  )
}

function LineText({ line, tone, caret }: { line: DiffLine; tone: DiffTone; caret?: boolean }) {
  const t = TONES[tone]
  const word = line.kind === "add" ? t.addWord : t.removeWord
  return (
    <>
      {line.kind !== "context" ? <span className="sr-only">{srLabel(line)}</span> : null}
      {line.segments ? <Segments segments={line.segments} word={word} /> : line.text}
      {caret ? <StreamingCaret /> : null}
    </>
  )
}

function SplitCell({
  line,
  side,
  tone,
  caret,
}: {
  line?: DiffLine
  side: "old" | "new"
  tone: DiffTone
  caret?: boolean
}) {
  if (!line) {
    return <div aria-hidden="true" className="bg-(color:--chatcn-alpha-100) min-h-5" />
  }
  const changed = line.kind !== "context"
  return (
    <div
      data-slot="diff-line"
      data-diff-line={line.kind}
      className={cn("relative flex min-h-5 min-w-0", rowTone(line.kind, tone))}
    >
      <Num
        value={side === "old" ? line.oldNumber : line.newNumber}
        strong={changed}
        gutter={gutterTone(line.kind, tone)}
      />
      <Glyph kind={line.kind} tone={tone} />
      <code className="min-w-0 flex-1 pe-3 font-[inherit] [overflow-wrap:anywhere] whitespace-pre-wrap">
        <LineText line={line} tone={tone} caret={caret} />
      </code>
    </div>
  )
}

const UnifiedRow = React.memo(function UnifiedRow({
  line,
  tone,
  wrap,
  caret,
  numbers = "both",
}: {
  line: DiffLine
  tone: DiffTone
  wrap: boolean
  caret?: boolean
  numbers?: NumberColumns
}) {
  const changed = line.kind !== "context"
  const gutter = gutterTone(line.kind, tone)
  return (
    <div
      data-slot="diff-line"
      data-diff-line={line.kind}
      className={cn("relative flex min-h-5", rowTone(line.kind, tone))}
    >
      {numbers !== "new" ? <Num value={line.oldNumber} strong={changed} gutter={gutter} /> : null}
      {numbers !== "old" ? <Num value={line.newNumber} strong={changed} gutter={gutter} /> : null}
      <Glyph kind={line.kind} tone={tone} />
      <code
        className={cn(
          "min-w-0 flex-1 pe-4 font-[inherit]",
          wrap ? "[overflow-wrap:anywhere] whitespace-pre-wrap" : "whitespace-pre",
        )}
      >
        <LineText line={line} tone={tone} caret={caret} />
      </code>
    </div>
  )
})

function Lines({
  lines,
  view,
  tone,
  wrap,
  caret,
  numbers,
}: {
  lines: DiffLine[]
  view: DiffView
  tone: DiffTone
  wrap: boolean
  caret?: boolean
  numbers?: NumberColumns
}) {
  const last = lines[lines.length - 1]
  const [scrollRef, scrolls] = useScrollsX<HTMLDivElement>(view !== "split" && !wrap)
  if (view === "split") {
    const rows = splitRows(lines)
    return (
      // One divider for the whole hunk, so it runs through the top and bottom padding too.
      <div className="before:bg-(color:--chatcn-border) relative py-1 before:absolute before:inset-y-0 before:start-1/2 before:w-px">
        {rows.map((row, i) => {
          const tail = caret && (row.left === last || row.right === last)
          return (
            <div
              key={`${row.left?.oldNumber ?? ""}-${row.right?.newNumber ?? ""}-${i}`}
              className="grid grid-cols-2"
            >
              <SplitCell
                line={row.left}
                side="old"
                tone={tone}
                caret={tail && row.left === last && !row.right}
              />
              <SplitCell
                line={row.right}
                side="new"
                tone={tone}
                caret={tail && row.right === last}
              />
            </div>
          )
        })}
      </div>
    )
  }
  return (
    // biome-ignore lint/a11y/useAriaPropsSupportedByRole: the label only applies while role="group" is set
    <div
      ref={scrollRef}
      // A hunk wider than the viewer scrolls sideways, so the keyboard has to be able to reach it.
      tabIndex={scrolls ? 0 : undefined}
      role={scrolls ? "group" : undefined}
      aria-label={scrolls ? "Changed lines, scrolls sideways" : undefined}
      className={cn(
        "py-1",
        !wrap && "chatcn-scroll overflow-x-auto",
        "focus-visible:outline-(color:--chatcn-accent) outline-none focus-visible:outline-2 focus-visible:-outline-offset-2",
      )}
    >
      <div className={cn(!wrap && "w-max min-w-full")}>
        {lines.map((line) => (
          <UnifiedRow
            key={`${line.kind}-${line.oldNumber ?? ""}-${line.newNumber ?? ""}`}
            line={line}
            tone={tone}
            wrap={wrap}
            caret={caret && line === last}
            numbers={numbers}
          />
        ))}
      </div>
    </div>
  )
}

function rangeLabel(hunk: DiffHunk) {
  const from = hunk.newLines === 0 ? hunk.oldStart : hunk.newStart
  const count = hunk.newLines === 0 ? hunk.oldLines : hunk.newLines
  return count <= 1 ? `Line ${from}` : `Lines ${fmt(from)} to ${fmt(from + count - 1)}`
}

