function Hunk({
  hunk,
  index,
  count,
  view,
  tone,
  wrap,
  review,
  streaming,
  decision,
  gap,
  gapExpandable,
  gapOpen,
  extra,
  peek,
  active,
  numbers,
  onDecide,
  onExpandGap,
  onPeek,
  onFocusHunk,
  hunkRef,
}: HunkProps) {
  const writing = streaming && !hunk.complete
  const collapsed = decision !== undefined && !peek
  const showGap = Boolean(gap && !gapOpen)
  // Read-only, the expander row also carries the hunk heading, the way GitHub does. While reviewing
  // it stands alone: Accept and Reject sit on the hunk's own row, so they never read as acting on
  // the hidden lines.
  const merged = showGap && !review
  const band = !merged && Boolean(hunk.heading || review || writing)
  const above = index > 0 || showGap || extra.length > 0
  const label = [
    `Change ${index + 1} of ${count}`,
    `${hunk.additions} added, ${hunk.deletions} removed`,
    decision,
  ]
    .filter(Boolean)
    .join(", ")

  return (
    // biome-ignore lint/a11y/useSemanticElements: a focusable review unit, not a form fieldset
    <div
      ref={hunkRef}
      role="group"
      aria-label={label}
      tabIndex={active ? 0 : -1}
      onFocus={(event) => {
        if (event.target === event.currentTarget) onFocusHunk()
      }}
      data-slot="diff-hunk"
      data-index={index}
      data-hunk-state={writing ? "streaming" : (decision ?? "pending")}
      className={cn(
        "group/hunk relative outline-none",
        "focus-visible:outline-(color:--chatcn-accent) focus-visible:outline-2 focus-visible:-outline-offset-2",
      )}
    >
      {showGap && gap ? (
        <GapRow
          count={gap.count}
          expandable={gapExpandable}
          onExpand={onExpandGap}
          heading={merged ? hunk.heading : undefined}
          writing={merged && writing}
          className={cn(index > 0 && "border-(color:--chatcn-border) border-t")}
        />
      ) : null}

      {extra.length > 0 ? (
        // Expanded context belongs above the hunk's header, and stays visible when the hunk collapses.
        <div dir="ltr" className="text-[0.8125rem]/[1.25rem] font-mono">
          <Lines lines={extra} view={view} tone={tone} wrap={wrap} numbers={numbers} />
        </div>
      ) : null}

      {band ? (
        <div
          data-slot="diff-hunk-header"
          className={cn(
            "bg-(color:--chatcn-inset) text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) flex min-h-9 flex-wrap items-center gap-x-2 gap-y-0.5 py-1 ps-3.5 pe-3.5",
            above && "border-(color:--chatcn-border) border-t",
          )}
        >
          {hunk.heading ? (
            <span dir="ltr" className="min-w-0 truncate font-mono" title={hunk.heading}>
              {hunk.heading}
            </span>
          ) : (
            <span className="tabular-nums">{rangeLabel(hunk)}</span>
          )}
          {writing ? (
            <ShimmerText className="text-[0.75rem]/[1rem] ms-auto">Writing</ShimmerText>
          ) : review ? (
            <HunkActions
              decision={decision}
              peek={peek}
              additions={hunk.additions}
              deletions={hunk.deletions}
              tone={tone}
              onDecide={onDecide}
              onPeek={onPeek}
            />
          ) : null}
        </div>
      ) : null}

      {collapsed ? null : (
        <div dir="ltr" className="text-[0.8125rem]/[1.25rem] font-mono">
          <Lines
            lines={hunk.lines}
            view={view}
            tone={tone}
            wrap={wrap}
            caret={writing}
            numbers={numbers}
          />
        </div>
      )}
    </div>
  )
}

/** The unchanged lines of a gap, when the file has a `source`. */
function gapLines(file: DiffFile, gap: DiffGap): DiffLine[] {
  if (!file.source) return []
  const out: DiffLine[] = []
  for (let c = 0; c < gap.count; c++) {
    const text = file.source.old[gap.oldFrom - 1 + c]
    if (text === undefined) break
    out.push({ kind: "context", text, oldNumber: gap.oldFrom + c, newNumber: gap.newFrom + c })
  }
  return out
}

/** `src/app/page.tsx` to `{ dir: "src/app/", name: "page.tsx" }`. */
function splitPath(path: string) {
  const slash = path.lastIndexOf("/")
  return slash === -1
    ? { dir: "", name: path }
    : { dir: path.slice(0, slash + 1), name: path.slice(slash + 1) }
}

/**
 * Splits a file name for middle truncation: the head may shrink to an ellipsis, the tail (the end
 * of the stem plus the extension) always stays, so "navigation-provider.tsx" reads "navig…ider.tsx".
 */
function splitName(name: string, keep = 8) {
  if (name.length <= keep + 4) return { head: name, tail: "" }
  return { head: name.slice(0, -keep), tail: name.slice(-keep) }
}

/** A path with the directory dimmed, so the file name is what the eye lands on. */
export function DiffPath({ path, className }: { path: string; className?: string }) {
  const { dir, name } = splitPath(path)
  const { head, tail } = splitName(name)
  return (
    <span
      data-slot="diff-path"
      dir="ltr"
      className={cn("flex min-w-0 font-mono", className)}
      title={path}
    >
      {/* The folder gives way first; the name only truncates when it alone does not fit, in the
          middle so the extension stays, and always leaves 2ch for the folder's ellipsis. */}
      {dir ? (
        // Gives way from its start, so the nearest folder stays ("…/runs/page.tsx").
        <span className="text-(color:--chatcn-fg-subtle) min-w-0 truncate [direction:rtl]">
          <span className="[direction:ltr] [unicode-bidi:isolate]">{dir}</span>
        </span>
      ) : null}
      <span className="text-(color:--chatcn-fg) flex max-w-[calc(100%-2ch)] min-w-0 shrink-0 font-medium">
        <span className="min-w-0 truncate">{head}</span>
        {tail ? <span className="shrink-0">{tail}</span> : null}
      </span>
    </span>
  )
}

